changeSet.sql:
DO $$
DECLARE
    message_id bigint;
    stored_number numeric;
    object_id oid;
BEGIN
    FOR message_id, stored_number IN
        SELECT id, CAST(tool_activity AS numeric) FROM iris_message WHERE tool_activity ~ '^[0-9]+$'
    LOOP
        object_id := NULL;
        -- Guarded in its own statement rather than as one condition, because an AND is not evaluated
        -- left to right: a number beyond an oid is also beyond the bigint the cast to oid goes through.
        IF stored_number <= 4294967295 THEN
            object_id := CAST(CAST(stored_number AS bigint) AS oid);
        END IF;
        IF object_id IS NOT NULL AND EXISTS (SELECT 1 FROM pg_largeobject_metadata WHERE oid = object_id) THEN
            UPDATE iris_message SET tool_activity = convert_from(lo_get(object_id), 'UTF8') WHERE id = message_id;
            PERFORM lo_unlink(object_id);
        ELSE
            UPDATE iris_message SET tool_activity = NULL WHERE id = message_id;
        END IF;
    END LOOP;
END $$;
